import React, { useState } from "react";
import { FiEdit } from "react-icons/fi";
import { FaTrash } from "react-icons/fa";
import AdminEditProduct from "./AdminEditProduct";

export default function AdminProductList() {
  const [editModalOpen, setEditModalOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const products = [
    { id: 1, name: "Product Name", price: "100", stocks: 100 },
    { id: 2, name: "Product Name", price: "100", stocks: 100 },
    { id: 3, name: "Product Name", price: "100", stocks: 100 },
    { id: 4, name: "Product Name", price: "100", stocks: 100 },
    { id: 5, name: "Product Name", price: "100", stocks: 100 },
  ];

  const openEdit = (product) => {
    setSelectedProduct(product);
    setEditModalOpen(true);
  };

  return (
    <div className="w-full px-6 py-4">
      {/* Header Row */}
      <div className="grid grid-cols-6 font-bold text-black mb-3 px-4">
        <span>ID</span>
        <span className="col-span-2">PRODUCT NAME</span>
        <span>PRICE</span>
        <span>STOCKS</span>
        <span></span>
      </div>

      {/* Product Cards */}
      <div
        className="bg-white rounded-2xl shadow-md p-4"
        style={{ border: "3px solid #E1E1E1" }}
      >
        {products.map((p, index) => (
          <div
            key={index}
            className="grid grid-cols-6 items-center p-3 mb-3 rounded-xl"
            style={{ backgroundColor: "#E1E1E1" }}
          >
            <span>{p.id}</span>
            <span className="col-span-2">{p.name}</span>
            <span>{p.price}</span>
            <span className="font-bold">{p.stocks}</span>

            {/* Icons */}
            <div className="flex justify-end space-x-5 pr-3">
              <FiEdit
                size={20}
                color="#000000"
                className="cursor-pointer hover:scale-110 transition"
                onClick={() => openEdit(p)}
              />
              <FaTrash
                size={20}
                color="#FF0000"
                className="cursor-pointer hover:scale-110 transition"
              />
            </div>
          </div>
        ))}
      </div>

      {/* Edit Modal */}
      <AdminEditProduct
        isOpen={editModalOpen}
        onClose={() => setEditModalOpen(false)}
        product={selectedProduct}
      />
    </div>
  );
}
